use std::io::{BufRead, BufReader, Read, Write};
use std::net::{SocketAddr, TcpListener, TcpStream};
use std::thread;

// The pure part, as in part 1 (shortened): request line in, response text out.
fn respond(request_line: &str) -> String {
    let path = request_line.split_whitespace().nth(1).unwrap_or("/");
    let (status, body) = match path {
        "/" => ("200 OK", "Welcome!"),
        "/hello" => ("200 OK", "Hello from a thread!"),
        _ => ("404 Not Found", "Nothing here"),
    };
    format!(
        "HTTP/1.1 {status}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
        body.len()
    )
}

// Handles one connection: read the request, write the response.
fn handle(mut stream: TcpStream) {
    let mut reader = BufReader::new(&stream);
    let mut request_line = String::new();
    reader.read_line(&mut request_line).unwrap();
    // Read and ignore the header lines, up to the blank line.
    loop {
        let mut line = String::new();
        let n = reader.read_line(&mut line).unwrap();
        if n == 0 || line == "\r\n" {
            break;
        }
    }
    let response = respond(&request_line);
    stream.write_all(response.as_bytes()).unwrap();
}   // the stream is dropped here, which closes the connection

// The server: accept a fixed number of connections, one thread each.
fn serve(listener: TcpListener, connections: usize) {
    let mut handlers = Vec::new();
    for stream in listener.incoming().take(connections) {
        let stream = stream.unwrap();
        handlers.push(thread::spawn(move || handle(stream)));
    }
    for handler in handlers {
        handler.join().unwrap();
    }
}

// A tiny client: connect, send a request, read everything until the server closes.
fn fetch(addr: SocketAddr, path: &str) -> String {
    let mut stream = TcpStream::connect(addr).unwrap();
    write!(stream, "GET {path} HTTP/1.1\r\nHost: localhost\r\n\r\n").unwrap();
    let mut reply = String::new();
    stream.read_to_string(&mut reply).unwrap();
    reply
}

fn main() {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let addr = listener.local_addr().unwrap();
    println!("server is listening on 127.0.0.1 (the OS chose the port)");

    let paths = ["/", "/hello", "/nope"];
    let server = thread::spawn(move || serve(listener, paths.len()));

    let mut clients = Vec::new();
    for path in paths {
        clients.push(thread::spawn(move || fetch(addr, path)));
    }
    for (path, client) in paths.iter().zip(clients) {
        let reply = client.join().unwrap();
        let (head, body) = reply.split_once("\r\n\r\n").unwrap();
        println!("GET {path} -> {} | {body}", head.lines().next().unwrap());
    }
    server.join().unwrap();
    println!("server finished");
}

